/bin/bash -lc "cat > /tmp/halyard-review.cjs <<'JS'
const {chromium}=require('/tmp/claude-0/-root-design/f13cfb4d-b71e-4ed8-960a-ee0a8c2a8818/scratchpad/pwnode/node_modules/playwright-core');
const fs=require('fs');
(async()=>{
const browser=await chromium.launch({headless:true,executablePath:'/root/.cache/ms-playwright/chromium-1140/chrome-linux/chrome',args:['--no-sandbox','--no-zygote','--single-process','--headless=new']});
const page=await browser.newPage({viewport:{width:1100,height:800},deviceScaleFactor:1});
const svg=n=>'data:image/svg+xml;base64,'+fs.readFileSync(n).toString('base64');
await page.setContent("'`<html><style>*{box-sizing:border-box}body{margin:0;background:#e4e4de;font:12px Arial;color:#19483f}.panel{height:280px;margin:20px 20px 0;display:flex;align-items:center;justify-content:center;background:#f4f0e6}.dark{background:#19483f}.main{width:531px}.sizes{display:flex;align-items:center;gap:56px;margin:32px 64px}.sizes img{display:block}.sizes span{display:block;margin-top:16px;color:#19483f} .tiny{image-rendering:pixelated}</style><div class="panel"><img class="main" src="${svg('"'logo.svg')}\"></div><div class=\"panel dark\"><img class=\"main\" src=\""'${svg('"'logo-reversed.svg')}\"></div><div class=\"sizes\">"'${[128,32,16].map(s=>`<div><img src="${svg('"'mark.svg')}\" width=\""'${s}" height="${s}"><span>${s}px</span></div>`).join('"'')}<div><img class=\"tiny\" src=\""'${svg('"'mark.svg')}\" width=\"160\" height=\"160\"><span>Icon silhouette</span></div></div></html>"'`);
await page.screenshot({path:'"'/tmp/halyard-preview.png'});
await page.emulateMedia({colorScheme:'dark'});
await page.setContent("'`<body style="margin:0;background:#182522"><img src="${svg('"'mark.svg')}\" width=\"16\" height=\"16\"><img src=\""'${svg('"'mark.svg')}\" width=\"128\" height=\"128\"></body>"'`);
await page.screenshot({path:'"'/tmp/halyard-dark-check.png'});
console.log('Rendered light and dark previews.');
await browser.close();
})().catch(e=>{console.error(e);process.exit(1)});
